import {header,section,icon,go} from '../ui.js';
export function render(state) {
 return `${header('我的学习','留住每一次真实的尝试')}<div class="profile-heading"><span class="large-profile">N</span><div><h2>Namson</h2><p>日常英语学习者 · 样例档案</p></div></div><div class="profile-metrics"><div><strong>${state.completed.length}</strong><span>演示练习次数</span></div><div><strong>${state.reviews.length}</strong><span>演示复习点</span></div></div>${section('学习与数据')}<div class="settings-list">${go(`${icon('book')} 词书与个人资料 ${icon('arrow',18)}`,'library','settings-row')}${go(`${icon('plan')} 考试与历史成绩 ${icon('arrow',18)}`,'exam','settings-row')}${go(`${icon('bolt')} 计划与学习进度 ${icon('arrow',18)}`,'plan','settings-row')}<button class="settings-row" data-action="export">${icon('review')} 查看演示数据 <span>↗</span></button></div>${section('语音与增强')}<div class="setting-description"><div><h3>发音评测 SOE</h3><span class="disabled-pill">默认关闭</span></div><p>尚未接入。你仍可以跟读、自听、手动加入发音复习点。</p></div><button class="quiet-row" data-action="quiet" aria-pressed="${state.quiet}"><span>静音学习</span><span class="toggle ${state.quiet?'on':''}" aria-hidden="true"></span></button><p class="small-note left">浏览器朗读不保证每台设备都可用。没有朗读时，可看文本继续学习。</p><button class="secondary full" data-action="reset-preview">重置演示数据</button><details id="data-preview"><summary>浏览器演示保存说明</summary><p class="muted">保存使用本地浏览器存储，只用于界面体验。清除浏览器数据后会恢复初始样例；不与真实应用或云端同步。</p><pre id="data-json">点击“查看演示数据”查看当前状态。</pre></details>`;
}
